	    Wallet entity = addToTransactions(event.getWalletId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindWallet( entity );

    	// ------------------------------------------
